1. Create `apps/web/src/spacing.css`:
```css
/* The client's one spacing scale (#3225): every board stylesheet's gap, padding and margin names a step
   here, or is 0, auto, an em or % term, an env() or a viewport or container term (src/spacing.test.ts).
   A step is a length in px, smallest first, numbered from 1: 2px apart to 12px, where the board's own
   lengths sit, then 4px and 8px apart. A new step goes in order and raises the list in that test. */

:root {
  --space-1: 2px;
  --space-2: 4px;
  --space-3: 6px;
  --space-4: 8px;
  --space-5: 10px;
  --space-6: 12px;
  --space-7: 16px;
  --space-8: 20px;
  --space-9: 24px;
  --space-10: 32px;
  --space-11: 40px;
}
```
2. In `apps/web/src/index.css`, add `@import "./spacing.css";` on its own line right after `@import "./motion.css";`. The existing import-order regexes in `typescale.test.ts`, `surfaces.test.ts` and `motion.test.ts` anchor only on a prefix, so they still pass.
3. Save the script below as `/tmp/migrate-spacing.mjs`, outside the worktree, and run `node /tmp/migrate-spacing.mjs apps/web/src` from the repo root. Expect "rewrote 482 values; 4 left for hand" and four `MANUAL` lines.
```js
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
const SRC = process.argv[2];
const sheets = (dir) => readdirSync(dir).flatMap((n) => { const p = join(dir, n); return statSync(p).isDirectory() ? (n === "test" ? [] : sheets(p)) : n.endsWith(".css") ? [p] : []; });
const BOARD = sheets(SRC).map((p) => relative(SRC, p).replaceAll("\\", "/"))
  .filter((s) => s === "index.css" || (s.startsWith("game/") && !s.startsWith("game/deckbuilder/") && s !== "game/table.css"));
const STEPS = [2, 4, 6, 8, 10, 12, 16, 20, 24, 32, 40];
const MANUAL = new Set([28, 36, 48, 132]);
const PROP = /(?<![\w-])((?:grid-)?(?:row-|column-)?gap|padding(?:-(?:top|right|bottom|left|inline|block)(?:-(?:start|end))?)?|margin(?:-(?:top|right|bottom|left|inline|block)(?:-(?:start|end))?)?|--gap)(\s*:\s*)([^;}]+)/g;
const RAW = /(?<![\w.])(-?)(\d*\.?\d+)(px|rem)\b/g;
const nearest = (px) => { let best = 0; for (const s of STEPS) if (Math.abs(s - px) < Math.abs(best - px)) best = s; return best; };
let changed = 0, manual = 0;
for (const sheet of BOARD) {
  const path = join(SRC, sheet);
  const text = readFileSync(path, "utf8");
  const out = text.split(/(\/\*[\s\S]*?\*\/)/).map((part, i) => i % 2 === 1 ? part : part.replace(PROP, (_all, prop, colon, value) => {
    if (prop === "--gap") return prop + colon + value.replace(/^6px$/, "var(--space-3)").replace(/^4px$/, "var(--space-2)");
    return prop + colon + value.replace(RAW, (tok, sign, num, unit) => {
      const px = Number(num) * (unit === "rem" ? 16 : 1);
      if (px === 0) return tok;
      if (MANUAL.has(px)) { manual++; console.log(`MANUAL ${sheet}: ${prop}: ${value.trim()}`); return tok; }
      const best = nearest(px); changed++;
      if (best === 0) return "0";
      const step = `var(--space-${STEPS.indexOf(best) + 1})`;
      return sign === "-" ? `calc(${step} * -1)` : step;
    });
  })).join("");
  if (out !== text) writeFileSync(path, out);
}
console.log(`rewrote ${changed} values; ${manual} left for hand`);
```
